/**
 * Jinx Magician + Marionette: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Magician
 * Wiki: https://wiki.bloodontheclocktower.com/Marionette
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { demonInfo } from '#lib/core/rules/evil-info.ts';
import { ownJinxRules } from '#lib/core/rules/jinxes.ts';
import { marionetteAs } from './marionette.test-support.ts';

describe('Magician + Marionette jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'magician', 'marionette');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('magician')?.name).toBe('Magician');
		expect(data.byId.get('marionette')?.name).toBe('Marionette');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['magician', 'marionette'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['magician'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['marionette'])).not.toContain(jinx);
	});

	describe('while the Magician is alive, the Demon doesn’t know which neighbour is the Marionette', () => {
		// Seat 0 the Marionette (as the Chef), seat 1 the Imp, then the Magician.
		const base = marionetteAs('chef', ['imp', 'magician', 'empath', 'monk']);

		it("is data in the Magician's rules", () => {
			// Wiki: "If the Magician is alive, the Demon doesn't know which neighbor is the Marionette."
			expect(ownJinxRules(base.game, 'magician', 'marionette', base.characters)).toMatchObject({
				hidesPartnerSeat: true
			});
		});

		it('hides the Marionette from the Demon at Demon info', () => {
			// Wiki: "the Demon doesn't know which neighbor is the Marionette."
			expect(demonInfo(base.game, base.characters).neighbourHidden).toEqual({
				seats: [base.seat(0)],
				partner: 'marionette',
				hiddenBy: 'magician'
			});
		});

		it('shows the Marionette as usual once the Magician is dead', () => {
			// Wiki: "If the Magician is alive"
			const s = base.dies('magician');
			expect(demonInfo(s.game, s.characters).neighbourHidden).toBeUndefined();
		});
	});
});
